function downloadOutput() {
  if (!output.stage) return;
  const blob = new Blob([output.text()], { type: "text/plain" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = output.stage;
  a.click();
  URL.revokeObjectURL(a.href);
}

window.addEventListener("keydown", (e) => {
  const mod = e.ctrlKey || e.metaKey;
  if (mod && e.shiftKey && e.key.toLowerCase() === "s") {
    e.preventDefault();
    downloadOutput();
    return;
  }
  if (mod && (e.key === "Enter" || e.key.toLowerCase() === "s")) {
    e.preventDefault();
    runCompile();
  }
});

async function boot() {
  try {
    await loadFlowSource();
    await applyMode(ui.elements.modeSelect.value);
    runCompile();
  } catch (e) {
    ui.setStatus("flow load error", "err");
    ui.showError("Failed to load flow assets: " + e.message);
  }
}
boot();